CREATE TABLE `watchlist_entries` (`user_id` CHAR(36) NOT NULL, `symbol_id` INT UNSIGNED NOT NULL, `created_at` DATETIME(3) NOT NULL, PRIMARY KEY (`user_id`,`symbol_id`), CONSTRAINT `watchlist_user_fk` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `paper_account_archives` (`id` CHAR(36) NOT NULL, `user_id` CHAR(36) NOT NULL, `snapshot_json` JSON NOT NULL, `created_at` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), INDEX `paper_archives_user_created` (`user_id`,`created_at`), CONSTRAINT `paper_archives_user_fk` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `paper_reset_keys` (`paper_account_id` INT UNSIGNED NOT NULL, `client_order_id` VARCHAR(64) NOT NULL, PRIMARY KEY (`paper_account_id`,`client_order_id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `paper_automations` (`id` CHAR(36) NOT NULL, `user_id` CHAR(36) NOT NULL, `strategy_id` CHAR(36) NOT NULL, `strategy_version_id` INT UNSIGNED NOT NULL, `symbol_id` INT UNSIGNED NOT NULL, `timeframe` VARCHAR(8) NOT NULL, `status` VARCHAR(16) NOT NULL, `allocation_pct` DECIMAL(5,2) NOT NULL, `state_json` JSON NOT NULL, `created_at` DATETIME(3) NOT NULL, `updated_at` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), INDEX `automation_status` (`status`), INDEX `automation_user_symbol` (`user_id`,`symbol_id`), CONSTRAINT `automation_user_fk` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
